-- SafetyTraining v20.051
-- Reconcile the live CSP/CSE 120h + 40h update family.
-- 40 reusable didactic units, exact course/module composition, selected INAIL/Piemonte provenance.
-- Test Builder remains paused: no final-assessment question bank is created here.

DO $do$
DECLARE
  r jsonb;
  v_lu uuid;
  v_luv uuid;
  v_course uuid;
  v_cv uuid;
  v_module uuid;
  v_module_key text;
  v_enriched boolean;
  v_content jsonb;
  v_detail text := 'Unità costruita per sviluppare competenza applicativa del coordinatore. Il docente parte dalla norma o dal rischio, mostra come si traduce in una scelta di progettazione/coordinamento, usa documenti o schemi di cantiere e conclude con una decisione motivata e verificabile. Non è sufficiente conoscere l’articolo: occorre saper individuare chi fa cosa, in quale fase, con quale evidenza e quale condizione impone una modifica o uno stop.';
  v_update_detail text := 'L’aggiornamento parte da ciò che è cambiato: norma, tecnica, cantiere, organizzazione o conoscenze ricavate da eventi e controlli. Il coordinatore deve trasformare l’aggiornamento in capacità di riconoscere scostamenti, formulare decisioni motivate, aggiornare documenti e verificare che la misura venga attuata. Ogni unità comprende caso, produzione di un output e debriefing.';
BEGIN
  FOR r IN SELECT value FROM jsonb_array_elements($initial$
  [
    {"key":"csp:law:system","title":"Sistema legislativo e soggetti della prevenzione","summary":"Leggere il sistema delle fonti, gli obblighi e le responsabilità dei soggetti che interagiscono nel cantiere.","focus":["D.Lgs. 81/2008 e principi generali","datore di lavoro, dirigente, preposto, RSPP, medico, RLS","obblighi, deleghe e responsabilità","vigilanza e sistema sanzionatorio"],"case":"In un cantiere più soggetti impartiscono indicazioni contrastanti: ricostruire ruoli, poteri e flussi corretti."},
    {"key":"csp:law:title4","title":"Titolo IV: cantieri temporanei o mobili","summary":"Applicare definizioni, campo di applicazione e obblighi specifici del Titolo IV.","focus":["artt. 88-104","committente e responsabile dei lavori","impresa affidataria, esecutrice e lavoratori autonomi","notifica preliminare e adempimenti"],"case":"Un intervento parte con una sola impresa ma ne entra una seconda: stabilire cosa cambia negli obblighi di coordinamento."},
    {"key":"csp:law:csp","title":"CSP: compiti, PSC e fascicolo dell’opera","summary":"Tradurre i compiti del coordinatore in progettazione in scelte progettuali e documenti utili.","focus":["art. 91","PSC","fascicolo adattato alle caratteristiche dell’opera","scelte progettuali e organizzative"],"case":"Il progetto prevede manutenzioni future in copertura: individuare cosa il CSP deve far emergere già in progettazione."},
    {"key":"csp:law:cse","title":"CSE: verifica, coordinamento e intervento","summary":"Applicare i compiti del coordinatore in esecuzione senza confondere coordinamento e vigilanza datoriale.","focus":["art. 92","verifica POS","coordinamento imprese","contestazione, sospensione e segnalazione nei casi previsti"],"case":"Un’impresa modifica la sequenza di lavoro creando interferenza non prevista: definire azioni del CSE e aggiornamenti necessari."},
    {"key":"csp:law:contracts","title":"Appalti, subappalti e idoneità tecnico-professionale","summary":"Comprendere la catena contrattuale e i riflessi sulla sicurezza di cantiere.","focus":["idoneità tecnico-professionale","impresa affidataria","subappalto","cooperazione e coordinamento","costi sicurezza"],"case":"L’affidataria subappalta una lavorazione critica: verificare documenti, coordinamento e responsabilità operative."},
    {"key":"csp:law:documents","title":"Documentazione di cantiere e coerenza tra PSC, POS e piani specialistici","summary":"Valutare la coerenza tra documenti e lavoro reale.","focus":["PSC","POS","PiMUS","piani demolizione/bonifica ove applicabili","verbali e aggiornamenti"],"case":"Il POS descrive un ponteggio diverso da quello pianificato: stabilire quali verifiche e aggiornamenti sono necessari."},
    {"key":"csp:law:enforcement","title":"Organi di vigilanza, responsabilità e casi giurisprudenziali","summary":"Usare casi ed esiti ispettivi per comprendere confini del ruolo e omissioni tipiche.","focus":["organi di vigilanza","prescrizioni","responsabilità civili e penali","tracciabilità delle decisioni"],"case":"Analizzare un caso di infortunio con carenza di coordinamento distinguendo obblighi dei diversi soggetti."},
    {"key":"csp:tech:site-layout","title":"Organizzazione e layout del cantiere","summary":"Progettare viabilità, accessi, recinzioni, aree operative e logistica per ridurre interferenze.","focus":["viabilità interna","accessi e recinzioni","depositi e stoccaggi","servizi e impianti di cantiere"],"case":"Ridisegnare un layout con mezzi pesanti, pedoni e area di scarico sovrapposti."},
    {"key":"csp:tech:excavations","title":"Scavi, sbancamenti e opere di sostegno","summary":"Valutare instabilità, seppellimento, accessi e interferenze con sottoservizi.","focus":["stabilità fronti","armature e sostegni","accessi","sottoservizi","mezzi al ciglio"],"case":"Uno scavo cambia profondità dopo variante: aggiornare misure, distanze e coordinamento."},
    {"key":"csp:tech:height","title":"Lavori in quota e protezioni contro le cadute","summary":"Integrare protezioni collettive, accessi e sistemi individuali nella pianificazione.","focus":["parapetti e opere provvisionali","accessi","DPI anticaduta","coperture fragili","piano di recupero"],"case":"Una lavorazione su copertura viene anticipata prima del completamento dei parapetti: definire alternative e stop."},
    {"key":"csp:tech:scaffolds","title":"Ponteggi e opere provvisionali","summary":"Coordinare progetto, PiMUS, montaggio, trasformazioni e uso del ponteggio.","focus":["PiMUS","progetto ponteggio","ancoraggi","montaggio/smontaggio","uso da parte di più imprese"],"case":"Due imprese vogliono modificare contemporaneamente il ponteggio: definire gestione e autorizzazioni."},
    {"key":"csp:tech:lifting","title":"Sollevamento, gru e movimentazione carichi","summary":"Pianificare aree, interferenze e sequenze di sollevamento.","focus":["gru a torre e autogrù","carichi sospesi","piani di sollevamento","segnalazioni","interferenze tra apparecchi"],"case":"Due gru hanno aree di rotazione sovrapposte: definire regole di coordinamento e priorità."},
    {"key":"csp:tech:moving-machines","title":"Macchine movimento terra e viabilità di cantiere","summary":"Ridurre investimento, ribaltamento e collisioni tramite organizzazione degli spazi e delle fasi.","focus":["mezzi e pedoni","zone cieche","retromarce","rampe e piste","segnalatore"],"case":"Una pala lavora nella stessa area di una squadra a terra: progettare segregazione e sequenza."},
    {"key":"csp:tech:electric","title":"Impianti elettrici, linee e messa a terra","summary":"Coordinare impianti temporanei, linee esistenti e lavori in prossimità di parti attive.","focus":["impianto di cantiere","quadri e distribuzione","messa a terra","linee aeree/interrate","lavori elettrici"],"case":"Una gru viene riposizionata vicino a una linea aerea: rivalutare distanze e misure."},
    {"key":"csp:tech:demolition","title":"Demolizioni e lavori strutturali","summary":"Pianificare sequenze che evitino collassi incontrollati e sovrapposizioni pericolose.","focus":["sequenza demolizione","stabilità residua","puntellamenti","caduta materiali","zone di esclusione"],"case":"Una variante cambia la sequenza di demolizione: identificare effetti su stabilità e accessi."},
    {"key":"csp:tech:chemical","title":"Agenti chimici, polveri, silice, amianto e bonifiche","summary":"Riconoscere rischi di esposizione e coordinare lavorazioni che richiedono misure specialistiche.","focus":["polveri e silice","sostanze pericolose","amianto ove presente","ventilazione e segregazione","rifiuti contaminati"],"case":"Durante una ristrutturazione emerge materiale sospetto: definire stop, identificazione e gestione specialistica."},
    {"key":"csp:tech:physical","title":"Rumore, vibrazioni e altri agenti fisici","summary":"Coordinare esposizioni e interferenze derivanti da lavorazioni rumorose o vibranti.","focus":["rumore","vibrazioni","radiazioni ottiche","microclima","pianificazione temporale"],"case":"Programmare attività rumorose senza esporre inutilmente altre squadre."},
    {"key":"csp:tech:fire-confined","title":"Incendio, esplosioni e ambienti confinati","summary":"Gestire attività ad alto rischio con permessi, isolamento e piani di emergenza.","focus":["lavori a caldo","ATEX ove applicabile","spazi confinati","depositi infiammabili","emergenze"],"case":"Un lavoro a caldo viene programmato vicino a deposito temporaneo: definire eliminazione interferenza e controllo."},
    {"key":"csp:tech:ergonomic","title":"Movimentazione, ergonomia e rischi organizzativi","summary":"Integrare logistica e organizzazione per ridurre sovraccarichi, stress e condizioni di errore.","focus":["movimentazione manuale","logistica","turni e fatica","pressioni temporali","ordine e pulizia"],"case":"Un ritardo porta ad aumentare sovrapposizioni e straordinari: individuare effetti sul rischio."},
    {"key":"csp:tech:emergency","title":"Emergenze, primo soccorso e coordinamento multi-impresa","summary":"Costruire una risposta d’emergenza compatibile con fasi, accessi e presenza di più imprese.","focus":["esodo","antincendio","primo soccorso","accesso mezzi di soccorso","comunicazioni"],"case":"Una fase di scavo rende inutilizzabile il punto di raccolta originario: aggiornare il piano operativo."},
    {"key":"csp:method:psc","title":"Metodologia di elaborazione del PSC","summary":"Trasformare progetto, cronoprogramma e rischi interferenziali in prescrizioni e misure comprensibili.","focus":["analisi progetto","fasi e sottofasi","interferenze","misure e prescrizioni","tavole e cronoprogramma"],"case":"Da un progetto semplificato estrarre fasi, interferenze e prime misure del PSC."},
    {"key":"csp:method:costs","title":"Costi della sicurezza e pianificazione delle misure","summary":"Collegare misure di coordinamento e costi specifici evitando duplicazioni o omissioni.","focus":["stima costi sicurezza","misure PSC","apprestamenti","misure interferenziali","coerenza economica"],"case":"Confrontare due soluzioni di segregazione e identificare quali costi rientrano nella stima pertinente."},
    {"key":"csp:method:coordination","title":"Riunioni, verbali, comunicazione e gestione dei conflitti","summary":"Condurre coordinamento efficace e tracciabile tra soggetti con interessi e tempi diversi.","focus":["riunione coordinamento","verbale","briefing","gestione conflitto","follow-up"],"case":"Due imprese si attribuiscono reciprocamente la responsabilità di un’interferenza: condurre una riunione orientata a fatti e misure."},
    {"key":"csp:method:control","title":"Sopralluoghi, non conformità e gestione delle modifiche","summary":"Osservare il lavoro reale, registrare scostamenti e aggiornare coordinamento e documenti.","focus":["sopralluogo","non conformità","azioni correttive","varianti","tracciabilità"],"case":"Durante un sopralluogo emerge una lavorazione non pianificata: definire raccolta dati, azione immediata e aggiornamento."},
    {"key":"csp:practice:psc-draft","title":"Laboratorio PSC: analisi e prima stesura","summary":"Produrre parti di PSC a partire da un caso progettuale realistico.","focus":["descrizione opera","organizzazione cantiere","fasi","interferenze","misure"],"case":"Redigere in gruppo la struttura del PSC per un edificio con scavi, struttura, copertura e impianti."},
    {"key":"csp:practice:plans","title":"Laboratorio POS/PiMUS e coerenza documentale","summary":"Confrontare documenti delle imprese con PSC e condizioni reali.","focus":["lettura POS","PiMUS","coerenza misure","richieste integrazione","accettazione/verifica"],"case":"Individuare cinque incoerenze in un POS simulato rispetto al PSC e formulare richieste di integrazione."},
    {"key":"csp:practice:schedule","title":"Cronoprogramma e interferenze","summary":"Usare la sequenza temporale per eliminare o governare sovrapposizioni pericolose.","focus":["Gantt","fasi incompatibili","separazione spaziale","separazione temporale","milestone sicurezza"],"case":"Riprogrammare tre lavorazioni incompatibili minimizzando sovrapposizioni."},
    {"key":"csp:practice:inspection","title":"Simulazione di sopralluogo CSE","summary":"Eseguire un sopralluogo strutturato, distinguendo osservazioni, non conformità e azioni.","focus":["preparazione sopralluogo","osservazione","intervista","evidenze","verbale"],"case":"Analizzare una planimetria/foto-scenario con più criticità e redigere un verbale operativo."},
    {"key":"csp:practice:meeting","title":"Simulazione di riunione di coordinamento","summary":"Gestire un conflitto tra imprese e tradurlo in decisioni verificabili.","focus":["agenda","fatti","responsabilità operative","decisioni","scadenze e follow-up"],"case":"Role-play: affidataria, subappaltatore e CSE devono risolvere interferenza tra sollevamento e montaggio."},
    {"key":"csp:practice:integrated","title":"Caso integrato CSP/CSE e preparazione alla verifica finale","summary":"Integrare progettazione, documenti, sopralluogo, decisioni e comunicazione.","focus":["caso completo","PSC","POS","variante","sopralluogo","decisioni CSE"],"case":"Caso finale: variante progettuale in corso d’opera modifica accessi, cronoprogramma e sollevamenti; il corsista produce aggiornamenti e decisioni motivate."}
  ]::jsonb) LOOP
    v_module_key := CASE WHEN r->>'key' LIKE 'csp:law:%' THEN 'giuridico' WHEN r->>'key' LIKE 'csp:tech:%' THEN 'tecnico' WHEN r->>'key' LIKE 'csp:method:%' THEN 'metodologico' ELSE 'pratico' END;
    v_enriched := r->>'key' IN ('csp:tech:height','csp:tech:scaffolds','csp:tech:excavations','csp:practice:inspection','csp:practice:integrated');
    INSERT INTO public.learning_units(stable_key,title,summary,default_minutes,source_group,tags,active,metadata)
    VALUES(r->>'key',r->>'title',r->>'summary',240,'SafetyTraining csp-cse-v2',array['safetytraining','csp-cse','allegato-xiv',v_module_key],true,
      jsonb_build_object('module_key',v_module_key,'learner_ready',true,'teacher_ready',true,'didactic_version','csp-cse-v2') || CASE WHEN v_enriched THEN jsonb_build_object('source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-15','reuse_policy','reference_and_original_rewrite')) ELSE '{}'::jsonb END)
    ON CONFLICT(stable_key) DO UPDATE SET title=excluded.title,summary=excluded.summary,default_minutes=240,source_group=excluded.source_group,tags=excluded.tags,active=true,metadata=excluded.metadata,updated_at=now() RETURNING id INTO v_lu;
    v_content := jsonb_build_object('case',r->>'case','norm','D.Lgs. 81/2008 Titolo IV, art. 98 e Allegato XIV; norme tecniche e disposizioni specifiche richiamate in funzione dell’argomento.','quiz',jsonb_build_object('options',jsonb_build_array('Che sia presente in un documento','Che sia la più economica','Che sia coerente con fase reale, rischi/interferenze, responsabilità e possibilità di verifica','Che sia uguale a quella di altri cantieri'),'question','Qual è il criterio migliore per valutare una misura di coordinamento?','explanation','Una misura è efficace quando è specifica per il contesto, attuabile, assegnata e verificabile; la sola presenza documentale non basta.','correct_index',2),'focus',r->'focus','title',r->>'title','detail',v_detail,'minutes',240,'quality',jsonb_build_object('case_based',true,'learner_ready',true,'teacher_ready',true,'output_required',true),'summary',r->>'summary','visuals',jsonb_build_array('modello-farfalla-rischio.svg','procedura-operativa-5-fasi.svg','piramide-pericoli.svg'),'procedure',jsonb_build_array('descrivere il contesto e la fase di lavoro','identificare soggetti, pericoli e interferenze','verificare documenti e misure già previste','definire eliminazione/riduzione del rischio e responsabilità operative','registrare decisione, scadenza e verifica dell’efficacia'),'objectives',jsonb_build_array('inquadrare correttamente obblighi e rischio','trasformare il requisito in misura di coordinamento','leggere criticamente documenti e lavoro reale','motivare una decisione e definirne il follow-up'),'common_errors',jsonb_build_array('limitarsi a citare la norma senza tradurla in azione','confondere il ruolo del coordinatore con quello del datore di lavoro dell’impresa','accettare documenti formalmente presenti ma incoerenti con il lavoro reale','non aggiornare PSC/coordinamento dopo una variante significativa'),'delivery_note','Il materiale completo resta disponibile a docente e corsista. Le modalità ammesse di erogazione e la quota pratica restano regole di delivery separate dal contenuto didattico.','guided_activity',jsonb_build_array('brief iniziale del caso','analisi individuale o di gruppo','produzione di una decisione/documento','confronto tra soluzioni','debriefing con correzione motivata'),'didactic_version','csp-cse-v2','final_assessment',false,'teacher_expansion','Sviluppare l’unità con almeno un documento, una planimetria, un cronoprogramma o un caso. Chiedere ai corsisti di motivare le scelte, produrre un output concreto e confrontare alternative. Nelle unità pratiche il prodotto del laboratorio deve essere revisionato con feedback esplicito.');
    IF v_enriched THEN
      v_content := v_content || jsonb_build_object('evidence_sources',jsonb_build_array(jsonb_build_object('url','https://www.inail.it/portale/it/inail-comunica/news/notizia.2018.10.-quaderni-tecnici-per-i-cantieri-temporanei-o-mobili-sul-portale-inail-la-nuova-edizione.html','use','technical_reference','title','Quaderni tecnici per i cantieri temporanei o mobili','authority','INAIL','checked_on','2026-10-15'),jsonb_build_object('url','https://www.regione.piemonte.it/governo/bollettino/abbonati/2025/30/attach/dgr_01413_1050_23072025.pdf','use','asr2025_compliance_crosscheck','title','Indicazioni operative per la formazione alla salute e sicurezza - edizione 2025','authority','Regione Piemonte','checked_on','2026-10-15')),'teacher_source_prompt','Collegare il requisito normativo a una situazione di cantiere concreta: individuare pericolo, barriera collettiva prioritaria, verifica prima dell’uso, condizione di stop e azione correttiva.');
      INSERT INTO public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata) VALUES(v_lu,'inail-quaderni-cantieri','technical_reference','Riferimento per opere provvisionali, protezioni collettive, ancoraggi, cadute e procedure di cantiere.',date '2026-10-15','{}') ON CONFLICT(learning_unit_id,source_key,purpose) DO UPDATE SET relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
      INSERT INTO public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata) VALUES(v_lu,'piemonte-indicazioni-formazione-2025','compliance_crosscheck','Cross-check operativo delle regole formative successive al recepimento ASR 2025.',date '2026-10-15','{}') ON CONFLICT(learning_unit_id,source_key,purpose) DO UPDATE SET relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
    END IF;
    INSERT INTO public.learning_unit_versions(learning_unit_id,version_number,status,content,published_at) VALUES(v_lu,1,'draft',v_content,null) ON CONFLICT(learning_unit_id,version_number) DO UPDATE SET status='draft',content=excluded.content,published_at=null;
  END LOOP;

  FOR r IN SELECT value FROM jsonb_array_elements($updates$
  [
    {"key":"cspupd:normative","title":"Novità normative e interpretative per CSP/CSE","summary":"Aggiornare il quadro normativo e tradurre novità, interpelli e orientamenti in impatti operativi.","focus":["novità D.Lgs. 81/2008 e atti collegati","ASR 2025","interpelli e FAQ istituzionali","requisiti e aggiornamento","tracciabilità delle fonti"],"case":"Una novità interpretativa incide sulla modalità di aggiornamento e sui requisiti: definire cosa cambia davvero nei processi del coordinatore."},
    {"key":"cspupd:design","title":"Progettazione della sicurezza e prevenzione by design","summary":"Integrare sicurezza, manutenzione futura, accessi e sequenze già nelle scelte progettuali.","focus":["scelte progettuali","fascicolo opera","manutenibilità","BIM e coordinamento informativo ove usato","varianti progettuali"],"case":"Una copertura viene modificata eliminando un accesso previsto: valutare effetti su costruzione e manutenzione futura."},
    {"key":"cspupd:psc","title":"PSC dinamico, cronoprogramma e varianti","summary":"Aggiornare PSC e coordinamento quando progetto o sequenza cambiano.","focus":["PSC","cronoprogramma","interferenze","varianti","misure e costi"],"case":"Una variante anticipa impianti mentre opere strutturali sono ancora in corso: ridefinire interferenze e misure."},
    {"key":"cspupd:pos","title":"POS, PiMUS e verifica di coerenza","summary":"Migliorare la lettura critica dei documenti delle imprese rispetto a PSC e lavoro reale.","focus":["POS","PiMUS","piani specialistici","richieste integrazione","coerenza documentale/operativa"],"case":"Il POS è formalmente completo ma non descrive il metodo realmente osservato: impostare verifica e richiesta correttiva."},
    {"key":"cspupd:highrisk","title":"Lavorazioni ad alto rischio: quota, scavi, sollevamenti e demolizioni","summary":"Riesaminare le principali attività ad alta gravità con focus sulle interferenze.","focus":["cadute dall’alto","scavi","gru e sollevamenti","demolizioni","energie e zone di esclusione"],"case":"Un sollevamento eccezionale attraversa una zona dove prosegue un’altra attività: scegliere eliminazione o segregazione dell’interferenza."},
    {"key":"cspupd:agents","title":"Agenti pericolosi, bonifiche e rischi emergenti","summary":"Aggiornare gestione di chimico, polveri, amianto, silice, rumore e nuovi processi/materiali.","focus":["chimico","amianto","silice","rumore/vibrazioni","nuove tecnologie e materiali"],"case":"In ristrutturazione emerge un materiale non censito: definire stop, identificazione e ripianificazione."},
    {"key":"cspupd:contractors","title":"Catena degli appalti e coordinamento multi-impresa","summary":"Governare subappalti, affidataria, autonomi e continui cambi di soggetti.","focus":["affidataria","esecutrici","autonomi","subappalti","idoneità e coordinamento"],"case":"Un subappalto entra con poco preavviso su attività già sovrapposte: definire precondizioni per l’avvio."},
    {"key":"cspupd:inspection","title":"Sopralluogo CSE, non conformità e azioni","summary":"Rafforzare osservazione, verbalizzazione, escalation e verifica della chiusura.","focus":["sopralluogo","evidenze","non conformità","azioni correttive","art. 92 e interventi previsti"],"case":"Una deviazione già verbalizzata si ripete: stabilire escalation e condizioni per la prosecuzione."},
    {"key":"cspupd:communication","title":"Riunioni, leadership di coordinamento e conflitti","summary":"Gestire comunicazione tra soggetti con poteri e interessi diversi senza perdere il focus sul rischio.","focus":["riunioni","briefing","verbali","conflitto","decisioni e follow-up"],"case":"Affidataria e subappaltatore rifiutano di cambiare sequenza per motivi economici: condurre la decisione di coordinamento."},
    {"key":"cspupd:integrated","title":"Caso integrato di aggiornamento e verifica dell’apprendimento","summary":"Integrare novità, variante, documenti, sopralluogo e decisioni in un caso completo.","focus":["caso complesso","variante","PSC/POS","sopralluogo","azioni","verifica finale"],"case":"Una variante modifica logistica, gru e cronoprogramma mentre entrano nuove imprese: produrre piano di azione completo e motivato."}
  ]::jsonb) LOOP
    INSERT INTO public.learning_units(stable_key,title,summary,default_minutes,source_group,tags,active,metadata) VALUES(r->>'key',r->>'title',r->>'summary',240,'SafetyTraining csp-cse-update-v2',array['safetytraining','csp-cse','update','allegato-xiv'],true,jsonb_build_object('learner_ready',true,'teacher_ready',true,'didactic_version','csp-cse-update-v2')) ON CONFLICT(stable_key) DO UPDATE SET title=excluded.title,summary=excluded.summary,default_minutes=240,source_group=excluded.source_group,tags=excluded.tags,active=true,metadata=excluded.metadata,updated_at=now() RETURNING id INTO v_lu;
    v_content := jsonb_build_object('case',r->>'case','norm','D.Lgs. 81/2008 Titolo IV e Allegato XIV; Accordo Stato-Regioni 17/04/2025 Parte III; Interpello MLPS n. 1/2026 per la verifica finale negli aggiornamenti riconosciuti anche tramite seminari/convegni.','quiz',jsonb_build_object('options',jsonb_build_array('Lasciare invariati i documenti se i lavori sono già iniziati','Aggiornare solo il verbale finale','Rivalutare rischi/interferenze, aggiornare quanto necessario e verificare le nuove misure prima/proseguendo secondo condizioni controllate','Delegare la decisione all’impresa più grande'),'question','Quando una variante modifica fasi o interferenze, qual è la risposta corretta del coordinamento?','explanation','La variante deve essere assorbita dal sistema di coordinamento reale e documentale, con misure attuabili e verificate.','correct_index',2),'focus',r->'focus','title',r->>'title','detail',v_update_detail,'minutes',240,'quality',jsonb_build_object('case_based',true,'learner_ready',true,'teacher_ready',true,'output_required',true),'summary',r->>'summary','visuals',jsonb_build_array('modello-farfalla-rischio.svg','procedura-operativa-5-fasi.svg','stop-segnala-ripristina.svg'),'procedure',jsonb_build_array('ricostruire fatto o cambiamento','identificare obblighi, rischi e soggetti','confrontare con PSC/POS/procedure esistenti','decidere misura, responsabilità e tempistica','verificare attuazione ed efficacia'),'objectives',jsonb_build_array('riconoscere novità e impatto operativo','applicare il contenuto a un cantiere reale o simulato','produrre una decisione/documento verificabile','definire follow-up e prova di efficacia'),'common_errors',jsonb_build_array('aggiornamento solo nozionistico','riutilizzare modelli senza adattarli','accettare varianti operative non riflesse nei documenti','chiudere non conformità senza verifica sul campo'),'delivery_note','I materiali sono integralmente disponibili. Le modalità di erogazione/riconoscimento sono gestite come regole separate; la verifica finale dell’apprendimento resta requisito da gestire nel percorso.','guided_activity',jsonb_build_array('lettura del caso e dati mancanti','analisi individuale o gruppo','produzione dell’output','confronto tra alternative','feedback e criterio di verifica'),'didactic_version','csp-cse-update-v2','final_assessment',false,'teacher_expansion','Usare fonti normative aggiornate e un caso recente o realistico. Far produrre un output concreto: estratto PSC, verbale, matrice interferenze, richiesta integrazione o piano di azione. La spiegazione finale deve chiarire perché una scelta è corretta e quali alternative restano ammissibili.');
